('uin-it-support', 'Information Technology Support Specialist', 'Universitas Islam Negeri Jakarta', 'Jan 2026 – Jul 2026 · 7 mos', 'Kota Tangerang Selatan, Banten, Indonesia · On-site', 'Apprenticeship', false, '', ARRAY['Provided IT support for staff, including printer management, troubleshooting, and technical assistance for day-to-day operational needs.', 'Developed and utilized Python scripts to automate the generation of SPK BLU and BOPTN documents, improving document processing efficiency and consistency.', 'Managed administrative documents and data using Microsoft Excel to support digital administration and document management.', 'Assisted staff with operational and technical requirements by implementing simple Python-based automation solutions tailored to workflow needs.']::text[], ARRAY['Python', 'Microsoft Excel', 'IT Support', 'Document Automation']::text[], 1),
('himti-academic', 'Staff of Academic', 'HIMTI UIN Syarif Hidayatullah Jakarta', 'Jul 2025 – Jul 2026 · 1 yr 1 mo', 'Kota Tangerang Selatan, Banten, Indonesia · Hybrid', 'Organization', false, 'As part of the Academic Division at HIMTI UIN Jakarta, I supported the academic improvement of IT students by providing academic assistance through Academic Seminars and helping students access the resources and support they needed to achieve academic success.', ARRAY[]::text[], ARRAY['Academic Support', 'Academic Seminars']::text[], 2),
('stukka-frontend', 'Frontend Developer', 'STUKKA DIGITAL', 'Oct 2025 – Feb 2026 · 5 mos', 'Jakarta Metropolitan Area · Remote', 'Internship', false, '', ARRAY['Collaborated with a development team to build and deploy the STUKKA DIGITAL Event Organizer website from development to production.', 'Translated UI designs into responsive and pixel-perfect frontend interfaces using Laravel and Tailwind CSS.', 'Resolved technical issues involving mobile navigation and asset animations in a production server environment.', 'Used Git and GitHub to manage development workflows, synchronize code, and collaborate with team members.']::text[], ARRAY['Laravel', 'Tailwind CSS', 'JavaScript', 'React', 'Git', 'GitHub']::text[], 3),
('smk-it-assistant', 'Information Technology Specialist Assistant', 'SMK BUDI UTOMO', 'Dec 2022 – Feb 2023 · 3 mos', 'Jombang, East Java, Indonesia · On-site', 'Apprenticeship', false, '', ARRAY['Assisted in the development and deployment of the school''s internet network infrastructure to improve connectivity across the school environment.', 'Installed and configured CCTV systems in classrooms to support school security and monitoring.', 'Assisted in maintaining, repairing, and renovating computer laboratories for Accounting, Multimedia, and Computer and Network Engineering programs.', 'Provided technical support and troubleshooting for school IT infrastructure and computer laboratory equipment.']::text[], ARRAY['IT Infrastructure', 'CCTV', 'Technical Support', 'Computer Maintenance']::text[], 4),
('multimedia-network', 'Network Engineer', 'CV. Multimedia Pratama', 'Nov 2021 – Feb 2022 · 4 mos', 'Kota Malang, East Java, Indonesia · On-site', 'Apprenticeship', false, '', ARRAY['Installed, configured, and maintained residential WiFi networks using MikroTik routers and access points.', 'Diagnosed and resolved network connectivity and performance issues to maintain reliable internet services.', 'Optimized network signal strength, coverage, and stability through router and access point configuration.', 'Provided technical support and assisted in maintaining network reliability and security for clients.']::text[], ARRAY['MikroTik', 'WiFi', 'Network Configuration', 'Network Troubleshooting']::text[], 5)
